/** Task18-owned fixture only, never copied into the product backend. */
import {captureInsertedRow, reconcileRow, ensureLifecycleState} from "../../../convex-dev/lib/referenceLifecycle";
import {v,ConvexError} from "convex/values";
import {internalMutation,internalQuery} from "../../../convex-dev/_generated/server";
import * as writers from "../../../convex-dev/cliOperator/facts";
import {migrateEvidence} from "../../../convex-dev/cliOperator/factHistory";
import {provenance,CaptureBudget,digest,capture,endpoint} from "../../../convex-dev/lib/factHistoryProvenance";
function own(space:string){if(!space.startsWith("task18-"))throw new ConvexError("FIXTURE_OWNERSHIP_REQUIRED");}
export const seedFact=internalMutation({args:{memorySpaceId:v.string(),tenantId:v.optional(v.string()),factId:v.string(),userId:v.optional(v.string()),fact:v.optional(v.string()),sourceRef:v.optional(v.object({conversationId:v.optional(v.string()),memoryId:v.optional(v.string()),messageIds:v.optional(v.array(v.string()))})),supersedes:v.optional(v.string())},handler:async(ctx,args)=>{own(args.memorySpaceId);await ensureLifecycleState(ctx);const now=Date.now();const id=await captureInsertedRow(ctx,"facts",{...args,fact:args.fact??"owned fixture",factType:"custom",confidence:70,sourceType:"manual",tags:["task18-owned"],version:1,createdAt:now,updatedAt:now,supersedesEndpoint:args.supersedes?{state:"unknown",logicalFactId:args.supersedes}:{state:"absent"},supersededByEndpoint:{state:"absent"}});return ctx.db.get(id);}});
export const seedLegacy=internalMutation({args:{sourceFactId:v.id("facts"),userId:v.string()},handler:async(ctx,args)=>{const fact=await ctx.db.get(args.sourceFactId);if(!fact)throw new ConvexError("FIXTURE_SOURCE_REQUIRED");own(fact.memorySpaceId);const timestamp=Date.now();const eventId="task18-legacy-"+crypto.randomUUID();const e={eventId,factId:fact.factId,memorySpaceId:fact.memorySpaceId,action:"UPDATE" as const,userId:args.userId,oldValue:fact.fact,newValue:fact.fact,supersedes:fact.supersedes,supersededBy:fact.supersededBy,timestamp};const eventDocumentId=await captureInsertedRow(ctx,"factHistory",e);const snapshot=await provenance(ctx,fact,new CaptureBudget());return {eventDocumentId,snapshot:{...snapshot,evidence:{kind:"verified-migration" as const,reference:"task18-owned-contemporaneous-ledger",hash:digest({eventDocumentId,sourceFactId:fact._id,ownerUserId:fact.userId,tenantId:fact.tenantId,timestamp})}}};}});
export const removeSources=internalMutation({args:{ids:v.array(v.id("facts"))},handler:async(ctx,args)=>{if(args.ids.length>3)throw new ConvexError("FIXTURE_BATCH_LIMIT");for(const id of args.ids){const fact=await ctx.db.get(id);if(fact){own(fact.memorySpaceId);await ctx.db.delete(id);}}return {deleted:args.ids.length};}});
export const source=internalQuery({args:{id:v.id("facts")},handler:async(ctx,args)=>{const fact=await ctx.db.get(args.id);if(fact)own(fact.memorySpaceId);return fact;}});
export const metrics=internalQuery({args:{memorySpaceId:v.string()},handler:async(ctx,args)=>{own(args.memorySpaceId);const result=await ctx.db.query("facts").withIndex("by_memorySpace",q=>q.eq("memorySpaceId",args.memorySpaceId)).take(4);return {ids:result.map(f=>f._id),native:await ctx.meta.getTransactionMetrics()};}});

export const measureWriter=internalMutation({args:{operation:v.union(v.literal("store"),v.literal("update"),v.literal("updateInPlace"),v.literal("supersede"),v.literal("consolidate"),v.literal("deleteMany")),input:v.any()},handler:async(ctx,args)=>{own(args.input.memorySpaceId);const writer=writers[args.operation];if (!("_handler" in writer) || typeof writer._handler !== "function") throw new ConvexError("FIXTURE_HANDLER_UNAVAILABLE");const value=await writer._handler(ctx,args.input);return {value,native:await ctx.meta.getTransactionMetrics()};}});
export const factsInSpace=internalQuery({args:{memorySpaceId:v.string()},handler:async(ctx,args)=>{own(args.memorySpaceId);const rows=await ctx.db.query("facts").withIndex("by_memorySpace",q=>q.eq("memorySpaceId",args.memorySpaceId)).take(10);return rows;}});

export const removeLegacy=internalMutation({args:{memorySpaceId:v.string()},handler:async(ctx,args)=>{if(!args.memorySpaceId.startsWith("task18-py-parity-"))throw new ConvexError("FIXTURE_OWNERSHIP_REQUIRED");const rows=await ctx.db.query("factHistory").withIndex("by_history_legacy_space",q=>q.eq("scopeVersion",undefined).eq("memorySpaceId",args.memorySpaceId)).take(2);if(rows.length>1)throw new ConvexError("FIXTURE_AMBIGUOUS");for(const row of rows)await ctx.db.delete(row._id);return {deleted:rows.map(r=>r._id)};}});

export const seedOrigins=internalMutation({args:{memorySpaceId:v.string(),tenantId:v.optional(v.string()),logicalId:v.string(),registerSpace:v.optional(v.boolean()),bytes:v.optional(v.number()),memoryOwner:v.optional(v.string()),noMemoryConversation:v.optional(v.boolean())},handler:async(ctx,args)=>{own(args.memorySpaceId);const now=Date.now(),padding="x".repeat(Math.min(args.bytes??0,900000));const space=args.registerSpace===false ? (await ctx.db.query("memorySpaces").withIndex("by_tenant_memorySpaceId",q=>q.eq("tenantId",args.tenantId).eq("memorySpaceId",args.memorySpaceId)).unique())!._id : await captureInsertedRow(ctx,"memorySpaces",{memorySpaceId:args.memorySpaceId,tenantId:args.tenantId,type:"personal",participants:[],metadata:{},status:"active",createdAt:now,updatedAt:now});const conversationId="conversation-"+args.logicalId,memoryId="memory-"+args.logicalId;const conversation=await captureInsertedRow(ctx,"conversations",{conversationId,memorySpaceId:args.memorySpaceId,tenantId:args.tenantId,type:"user-agent",participants:{userId:"target",userIds:["collaborator"]},messages:[{id:"message",role:"user",content:padding,timestamp:now}],messageCount:1,createdAt:now,updatedAt:now});const memory=await captureInsertedRow(ctx,"memories",{memoryId,memorySpaceId:args.memorySpaceId,tenantId:args.tenantId,userId:args.memoryOwner,content:padding,contentType:"raw",sourceType:"conversation",sourceTimestamp:now,conversationRef:args.noMemoryConversation?undefined:{conversationId,messageIds:["message"]},importance:50,tags:[],version:1,previousVersions:[],createdAt:now,updatedAt:now,accessCount:0});return {space,conversation,memory,conversationId,memoryId};}});
export const duplicateSpace=internalMutation({args:{memorySpaceId:v.string(),tenantId:v.optional(v.string())},handler:async(ctx,args)=>{own(args.memorySpaceId);return captureInsertedRow(ctx,"memorySpaces",{...args,type:"personal",participants:[],metadata:{},status:"active",createdAt:Date.now(),updatedAt:Date.now()});}});

export const seedCycle=internalMutation({args:{memorySpaceId:v.string(),tenantId:v.optional(v.string())},handler:async(ctx,args)=>{own(args.memorySpaceId);const now=Date.now(),ids=[];for(const factId of ["fact-cycle-a","fact-cycle-b"])ids.push(await captureInsertedRow(ctx,"facts",{...args,factId,userId:"owner",fact:"cycle fixture",factType:"custom",confidence:50,sourceType:"manual",tags:[],version:1,createdAt:now,updatedAt:now,supersedesEndpoint:{state:"absent"},supersededByEndpoint:{state:"absent"}}));const a=(await ctx.db.get(ids[0]))!,b=(await ctx.db.get(ids[1]))!;const budget=new CaptureBudget(20);for(const [from,to] of [[a,b],[b,a]]){const patch={supersededBy:to.factId,supersededByEndpoint:endpoint(to)};await reconcileRow(ctx,from._id,patch);await capture(ctx,{...from,...patch},{action:"SUPERSEDE",oldValue:from.fact,newValue:to.fact,intent:{operationId:"task18-cycle-"+crypto.randomUUID(),phase:"fixture"},role:"source",kind:"fixture_cycle",request:args,affected:ids,result:to._id},budget);}return {ids,logical:a.factId};}});

function repairOwn(space:string){if(!space.startsWith("task18-repair1-")&&!space.startsWith("task18-repair2-")&&!space.startsWith("task18-repair3-"))throw new ConvexError("FIXTURE_REPAIR_OWNERSHIP_REQUIRED");}
export const configureLedgerRelationships=internalMutation({args:{id:v.id("facts"),previous:v.id("facts"),next:v.id("facts")},handler:async(ctx,args)=>{const fact=(await ctx.db.get(args.id))!,previous=(await ctx.db.get(args.previous))!,next=(await ctx.db.get(args.next))!;repairOwn(fact.memorySpaceId);for(const target of[previous,next])if(target.memorySpaceId!==fact.memorySpaceId||target.tenantId!==fact.tenantId)throw new ConvexError("FIXTURE_SCOPE_REQUIRED");await reconcileRow(ctx,fact._id,{supersedes:previous.factId,supersedesEndpoint:endpoint(previous),supersededBy:next.factId,supersededByEndpoint:endpoint(next)});return fact._id;}});
export const malformRelationship=internalMutation({args:{id:v.id("facts"),target:v.id("facts"),direction:v.union(v.literal("supersedes"),v.literal("supersededBy")),mode:v.union(v.literal("populatedAbsent"),v.literal("missingKnown"),v.literal("missingUnknown"),v.literal("knownMismatch"),v.literal("unknownMismatch"))},handler:async(ctx,args)=>{const fact=(await ctx.db.get(args.id))!,target=(await ctx.db.get(args.target))!;repairOwn(fact.memorySpaceId);if(target.memorySpaceId!==fact.memorySpaceId||target.tenantId!==fact.tenantId)throw new ConvexError("FIXTURE_SCOPE_REQUIRED");const saved=args.mode==="populatedAbsent"?{state:"absent" as const}:args.mode==="missingUnknown"?{state:"unknown" as const,logicalFactId:target.factId}:args.mode==="unknownMismatch"?{state:"unknown" as const,logicalFactId:"fact-forged"}:{...endpoint(target),logicalFactId:args.mode==="knownMismatch"?"fact-forged":target.factId};await ctx.db.patch(fact._id,{[args.direction]:args.mode.startsWith("missing")?undefined:target.factId,[args.direction==="supersedes"?"supersedesEndpoint":"supersededByEndpoint"]:saved});return fact._id;}});
export const historyDocument=internalQuery({args:{id:v.id("factHistory")},handler:async(ctx,args)=>{const event=await ctx.db.get(args.id);if(event)repairOwn(event.memorySpaceId);return event;}});
export const measureMigration=internalMutation({args:{input:v.any()},handler:async(ctx,args)=>{const id=ctx.db.normalizeId("factHistory",args.input.eventDocumentId);if(!id)throw new ConvexError("FIXTURE_EVENT_REQUIRED");const event=(await ctx.db.get(id))!;repairOwn(event.memorySpaceId);if (!("_handler" in migrateEvidence)||typeof migrateEvidence._handler!=="function")throw new ConvexError("FIXTURE_HANDLER_UNAVAILABLE");const value=await migrateEvidence._handler(ctx,args.input);return {value,native:await ctx.meta.getTransactionMetrics()};}});

export const removeOrigins=internalMutation({args:{space:v.id("memorySpaces"),memory:v.id("memories"),conversation:v.id("conversations")},handler:async(ctx,args)=>{const space=await ctx.db.get(args.space),memory=await ctx.db.get(args.memory),conversation=await ctx.db.get(args.conversation);if(space)repairOwn(space.memorySpaceId);if(memory)repairOwn(memory.memorySpaceId);if(conversation)repairOwn(conversation.memorySpaceId);if(space)await ctx.db.delete(space._id);if(memory)await ctx.db.delete(memory._id);if(conversation)await ctx.db.delete(conversation._id);return {deleted:[space?._id,memory?._id,conversation?._id].filter(Boolean)};}});

export const removeOriginRecord=internalMutation({args:{id:v.union(v.id("memories"),v.id("conversations"))},handler:async(ctx,args)=>{const row=await ctx.db.get(args.id);if(!row)throw new ConvexError("FIXTURE_SOURCE_REQUIRED");repairOwn(row.memorySpaceId);await ctx.db.delete(row._id);return {deleted:row._id};}});

export const seedBoundaryEvent=internalMutation({args:{sourceFactId:v.id("facts"),timestamp:v.number()},handler:async(ctx,args)=>{const fact=await ctx.db.get(args.sourceFactId);if(!fact||!fact.memorySpaceId.startsWith("task18-repair3-")||!Number.isFinite(args.timestamp))throw new ConvexError("FIXTURE_BOUNDARY_REQUIRED");const snapshot=await provenance(ctx,fact,new CaptureBudget());const eventId="task18-boundary-"+crypto.randomUUID();const id=await captureInsertedRow(ctx,"factHistory",{...snapshot,eventId,factId:fact.factId,memorySpaceId:fact.memorySpaceId,userId:"boundary-actor",action:"UPDATE",timestamp:args.timestamp,newValue:fact.fact});return ctx.db.get(id);}});
